import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static int[] tree;

    static void add(int i) {
        for (; i < tree.length; i += i & -i) tree[i]++;
    }

    static int query(int i) {
        int s = 0;
        for (; i > 0; i -= i & -i) s += tree[i];
        return s;
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt(), k = nextInt();
        long[] p = new long[n];
        for (int i = 0; i < n; i++) p[i] = nextLong();
        long[] sorted = p.clone();
        Arrays.sort(sorted);
        int m = 0;
        for (int i = 0; i < n; i++) if (i == 0 || sorted[i] != sorted[i - 1]) sorted[m++] = sorted[i];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) rank[i] = Arrays.binarySearch(sorted, 0, m, p[i]) + 1;
        int[] leftLess = new int[n];
        tree = new int[m + 1];
        for (int i = 0; i < n; i++) {
            leftLess[i] = query(rank[i] - 1);
            add(rank[i]);
        }
        tree = new int[m + 1];
        int answer = 0;
        for (int i = n - 1; i >= 0; i--) {
            int rightLess = query(rank[i] - 1);
            add(rank[i]);
            if (leftLess[i] >= k && rightLess >= k) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"slices"
	"sort"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(bufio.NewReader(os.Stdin))
	n, k := int(nextInt()), int(nextInt())
	p := make([]int64, n)
	for i := range p {
		p[i] = nextInt()
	}
	ordered := slices.Clone(p)
	slices.Sort(ordered)
	ordered = slices.Compact(ordered)
	m := len(ordered)
	rank := make([]int, n)
	for i, v := range p {
		rank[i] = sort.Search(m, func(j int) bool { return ordered[j] >= v }) + 1
	}
	tree := make([]int, m+1)
	add := func(i int) {
		for ; i <= m; i += i & -i {
			tree[i]++
		}
	}
	query := func(i int) int {
		s := 0
		for ; i > 0; i -= i & -i {
			s += tree[i]
		}
		return s
	}
	leftLess := make([]int, n)
	for i := 0; i < n; i++ {
		leftLess[i] = query(rank[i] - 1)
		add(rank[i])
	}
	clear(tree)
	answer := 0
	for i := n - 1; i >= 0; i-- {
		rightLess := query(rank[i] - 1)
		add(rank[i])
		if leftLess[i] >= k && rightLess >= k {
			answer++
		}
	}
	fmt.Println(answer)
}
